#!/bin/bash
# Owner-attended slpa runs (worklog 2026-11-05 10:02): arm one, tell the owner, reboot into it.
#   bash harness/psci-efi/attended.sh A|B|C [--dry]
# A: slpa (deep_steps 6), 30 s alarm; with the test kernel's ANS IO RVBAR restore since 11-05 17:36. B: A + PMU boot stage 0x50 (deep_steps 14). C: B + the PMP steps (pmp-sleep; IDLE sent once since 11-05 18:00).
# Image 52's Aura S2R steps (worklog 2026-11-05 evening), each with slpa: D: the PMGR's S2R timer (aura-ctl 1).
# E: D + every core into macOS's deep sleep (aura-ctl 3). F: the cores alone, no timer (aura-ctl 2), the control.
# Image 53 (worklog 2026-11-05, "image 53"): G: E + quiesceHW's power domains (aura-ctl 7). H: G + its ClkGen and
# PLL-off writes (aura-ctl 15), i.e. all of AppleT6020PMGR::quiesceHW but the cluster power-off, in macOS's order.
# I: C + H, the PMP's IDLE after slpa and the whole quiesce before the timer, as macOS does both (worklog 11-05 21:3x).
# Every run: image 53 (install.sh BIN2; aura-ctl 0 is image 51), 1 deep cycle, root read-only, the PMGR state
# counters on, dead-man switch.
# Run only when the owner has said they are at the Mac and ready to reset by hand.
set -eu
RUN=${1:?A to F}; DRY=${2:-}; ALARM=30
# REL=1 (default): the PMP's display requests released for sleep (pmp_report.test_release_aon, 11-05 18:16).
# NEXT="G H": after recording this run, the next session arms the first of these (owner still attended).
REL=${REL:-1}; NEXT=${NEXT:-}; AOP=0
# EXTRA="...": appended to the next session's prompt (e.g. what to run after this one).
EXTRA=${EXTRA:-}; KEY=0; WX=${WX:-}; PIDS=${PIDS:-}; KIND="OWNER-ATTENDED slpa run"
H=$(cd "$(dirname "$0")" && pwd)
L=/var/lib/deepidle
case $RUN in
    A) DS=6;  PMP=0; CTL=0 ;;
    B) DS=14; PMP=0; CTL=0 ;;
    C) DS=14; PMP=1; CTL=0 ;;
    D) DS=6;  PMP=0; CTL=1 ;;
    D2) DS=6; PMP=0; CTL=1; ALARM=90 ;;   # D with a later alarm: does the reset follow the alarm or the timer?
    E) DS=6;  PMP=0; CTL=3 ;;
    F) DS=6;  PMP=0; CTL=2 ;;
    G) DS=6;  PMP=0; CTL=7 ;;    # image 53: E + quiesceHW's domains (AFR off, SIO auto-enable off)
    H) DS=6;  PMP=0; CTL=15 ;;   # image 53: G + quiesceHW's ClkGen and PLL-off writes
    I) DS=14; PMP=1; CTL=15 ;;   # C + H: the PMP's IDLE and all of image 53's quiesceHW before the timer, as macOS
    J) DS=14; PMP=1; CTL=31; AOP=3 ;;   # I + the AOP's sleep handshake + image 54's soc-cluster power-off: all of macOS's steps found
    K) DS=14; PMP=1; CTL=15; AOP=3 ;;   # J without the cluster power-off (I + the AOP handshake), if J resets in a new way
    L) DS=30; PMP=1; CTL=31; AOP=3 ;;
    M) DS=30; PMP=1; CTL=31; AOP=3; KEY=1 ;;   # L with the owner pressing the power key once ~3 min after the push: does the key wake it, and did the SoC sleep?   # J + macOS's AP wake mask (deep_steps bit 16): D to J all ran with every wake source enabled
    W) DS=16; PMP=0; CTL=0; AOP=3; KIND="UNATTENDED normal-path (no slpa) wake-bisect run"
       [ -n "$WX" ] || { echo "W needs WX=w0,...,w8 (tools/wake-bisect.py next)"; exit 2; } ;;   # macOS's mask + WX, no slpa: does the alarm wake Aura's deep WFI?
    P) DS=0; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; KIND="UNATTENDED normal-path (no slpa) check run" ;;   # ISP_SYS's PMP request withdrawn for sleep too: does it ack, and come back?
    N) DS=30; PMP=1; CTL=31; AOP=3; PIDS=${PIDS:-0x1000} ;;   # L + ISP_SYS released: the PMP's request word at 0 before slpa, as macOS's trace
    *) echo "run A to N, P, W"; exit 2 ;;
esac
findmnt /boot >/dev/null || { echo "/boot is not mounted"; exit 1; }
[ "$(sha256sum /boot/m1n1/boot.bin | cut -c1-16)" = 76f850895fed53d1 ] || { echo "ESP boot.bin is not the default"; exit 1; }
echo "run $RUN: deep_steps=$DS pmp-sleep=$PMP aura-ctl=$CTL pmp-release=$REL aop=$AOP wake-extra=${WX:-none} pmp-release-ids=${PIDS:-none}, 1 deep cycle, $ALARM s alarm, counters on; next: ${NEXT:-none}"
[ "$DRY" = --dry ] && exit 0
echo $DS | sudo tee $L/deep-steps >/dev/null
echo 1 | sudo tee $L/suspend-cycles >/dev/null
echo $ALARM | sudo tee $L/suspend-alarm >/dev/null
echo deep | sudo tee $L/sleep-modes >/dev/null
sudo touch $L/pmgr-counters $L/force-ro
if [ $PMP = 1 ]; then sudo touch $L/pmp-sleep; else sudo rm -f $L/pmp-sleep; fi
if [ $CTL != 0 ]; then echo $CTL | sudo tee $L/aura-ctl >/dev/null; else sudo rm -f $L/aura-ctl; fi
# aop.sleep_ap_idle (worklog 2026-11-05 23:55): 0 none (runs A to I), 3 the AOP queue stop and 0x201 before slpa
echo $AOP | sudo tee $L/aop-sleep-mode >/dev/null
if [ -n "$WX" ]; then echo "$WX" | sudo tee $L/wake-extra >/dev/null; else sudo rm -f $L/wake-extra; fi
if [ -n "$PIDS" ]; then echo "$PIDS" | sudo tee $L/pmp-release-ids >/dev/null; else sudo rm -f $L/pmp-release-ids; fi
if [ $REL = 1 ]; then echo deep | sudo tee $L/pmp-release-modes >/dev/null; else sudo rm -f $L/pmp-release-modes; fi
sudo rm -f $L/discharge $L/poke-wakemask
sudo bash $H/install.sh suspendall | tail -1
if [ $RUN = W ] || [ $RUN = P ]; then
agent-notify send --title "S2R wake-bisect run: starting" --tags "robot" --message \
"Unattended, no slpa (run $RUN, wake_extra=${WX:-none}, pmp-release-ids=${PIDS:-none}): the Mac reboots in ~30 s, suspends ~2 min later and either wakes on the $ALARM s alarm or resets itself on the watchdog. Nothing to do." | tail -1
else
agent-notify send --title "S2R run $RUN: starting now" --priority high --tags "robot,warning" --message \
"Mac reboots in ~30 s; screen stays dark. ~2 min: it suspends with slpa; $ALARM s later the alarm. Don't touch keys, trackpad or lid.$( [ $KEY = 1 ] && echo "
THIS RUN: press the power key ONCE, briefly, 3 min after this push (not before 2:50, not after 3:40); tell me the time you pressed it." )
1) Works or resumes: result in the chat within ~6 min.
2) Disk dead: a high-priority 'Mac dead-man switch' push; the Mac resets itself. Nothing to do.
3) No chat message and no push within 10 min: hold power ~10 s until off, wait 5 s, press once. Then tell me 'reset by hand' and when." | tail -1
fi
P=$(mktemp)
cat > $P <<E
First remove ~/.local/state/deepidle/resume. This boot is $KIND $RUN (worklog 2026-11-05 10:02; D to F: the evening entry on image 52; G, H: image 53): image 53, deep_steps=$DS, pmp-sleep=$PMP, aura-ctl=$CTL (1 PMGR S2R timer, 2 every core into macOS's deep sleep, 4 quiesceHW's domains, 8 its ClkGen/PLL-off; psci_dbg[19..22] the AFR, SIO, SIO_CPU and PLL-off registers before<<32|after, [23] poll timeouts; run.sh logs 'aura ctl', psci_dbg[17] 0x53000000xx = the word Aura read, [18] 1 = timer written), 1 deep cycle, $ALARM s alarm, PMGR counters on, root ro, dead-man switch. FIRST read the ntfy "Mac dead-man switch" pushes (worklog 2026-11-05 15:57: they hold the resume, the counters, aura dbg and SART lines; never print the topic). Then work out what happened from uptime vs resume.log, the Pi watcher kmsg and the newest results-psci-efi-suspendall-*/run.log: a resume (read 'pmgr counters after deep 1': SLP_S2R / SYS_S2R_AOP above 0 = the SoC went down; psci_dbg[13] 3 = it came back through RVBAR with no wake line; apple-sart lines; nvme errors; the dead-man regs), or a reset (time from echo mem to the next kernel start: about 144 s = WD1 at 120 s, i.e. with aura-ctl 2 or 3 the cores powered down but the SoC never restarted them, as images 32 to 36; about 204 s = Linux resumed through RVBAR then hung; 94 s cold boot; 124 s SMC timeout; ask the owner if they reset by hand). Read-only btrfs scrub if any btrfs error appeared. Then remove deep-steps, pmp-sleep, aura-ctl, pmp-release-modes, pmgr-counters, force-ro, aop-sleep-mode, wake-extra, pmp-release-ids; check boot.bin 76f850895fed53d1 and next_entry unset. Record in the worklog, s2r-status.json, status.md and the board; push GH-8 and main; tell the owner the result right away.$( [ $RUN = D2 ] && echo " D2 reading (worklog entry 'run D'): next kernel about 86 s after echo mem = the S2R timer's own reset, independent of the alarm; about the alarm + 56 s (about 146 s) = the SoC slept and the alarm cold-booted it; a dead-man push = Linux resumed with the SoC up." )$( [ $RUN = E ] && echo " E reading (worklog entry 'run D2'): the S2R timer alone resets about 85 s after echo mem (D, D2). E adds every core into macOS's deep sleep: about 85 s again = the timer needs quiesceHW's clock/PLL steps too; about 144 s = WD1, the cores went down but the SoC never took over; a resume (pmgr counters SLP_S2R > 0, psci_dbg[13] 3) or a reset timed by the 30 s alarm = the SoC got further." )$( [ $RUN = F ] && echo " F reading (worklog entry 'run E'): D, D2 and E all reset about 85 s after echo mem (the S2R timer). F has the cores without the timer: about 144 s (WD1) = the cores really power down and nothing restarts them; a dead-man push or a resume on the 30 s alarm = bit 2 does not really power the cores down, so E did not test what it meant to." )$( [ $RUN = A ] && echo " A reading (worklog entries 'IO RVBAR', 17:36 and 17:41): the test kernel restores the ANS wrapper's IO RVBAR (0x347050000). In run.log or the dead-man push: 'TEST iorvbar: kept 0x10000004001' = slpa does not clear it (the lead is wrong; the ANS fails for another reason); 'was 0x..., restored 0x10000004001' then the disk answers = the fix works; restored but 'ANS did not boot' again = the IO RVBAR is one of several things slpa resets (read the dead-man IORVBAR word and ANS cpu status)." )$( [ $RUN = C ] && echo " C reading (worklog entry 'the PMP crash in run C was a double SetAPPower'): the test kernel now sends the PMP's IDLE once (run C on 16:01 crashed the PMP by sending SetAPPower 0x201 twice: the firmware panics 'Invalid AP power'). 'PMP SetAPPower/SetIOPPower IDLE: 0' = the PMP accepted macOS's step 5; then read the PMGR counters (SLP_S2R > 0 = the SoC went further) and whether the PMP answers after the wake (on 10-23 its wake from IDLE failed without a power cycle). A PMP crash again = read its crashlog lines in the dead-man push or run.log." )$( case $RUN in J|K) echo " $RUN reading (J adds aura-ctl 16, image 54: the five soc-clusters' targets to 0 before the clocks; psci_dbg[6..10] before<<32|after, unattended 11-06 00:18 gave PACC0/1 0x10, ANE0/AVEMSR 0x00, DISPLAY 0x10 with its bit-4 poll timing out)." ;; esac )$( case $RUN in J|K) echo " J/K reading (worklog 2026-11-05 23:21 to 2026-11-06 00:01, the AOP's sleep handshake): run I reset about 85 s after echo mem. J adds what macOS tells the AOP before slpa: dmesg 'TEST queues stopped for system sleep: 12 of 12' and 'TEST SetAPPower 0x201 for system sleep: 0' before 'MBSE = slpa'. PMGR counters SYS_S2R_AOP or SLP_S2R above 0 = the SoC went further; about 85 s again = the AOP was not what the entry waited for either. An AOP crash line = read its PC (0x1002880 was the ring writer)." ;; esac )$( [ $RUN = L ] && echo " L reading (worklog 2026-11-06 'run J' and 'macOS's own wake mask' entries; since 16:10 the mask step works, ioremap_np): J reset 86 s after echo mem with the AOP's queues stopped (12 of 12) and its 0x201 acked. Runs D to J all ran with Linux's wake mask (all 0, every PMGR wake source enabled); L writes macOS's mask (only its 22 sources) in suspend_late before slpa ('sleep: wake mask ... -> ...'). About 85 s again = a pending wake source was not what held the entry; about 145 s = WD1 (the mask blocked Aura's heartbeat, worklog 11-05 08:00, and the entry still did not complete); a dead-man push or a resume = read 'sleep: wake status' (which source woke it) and the PMGR counters (SLP_S2R / SYS_S2R_AOP > 0 = the SoC slept). If nothing comes back and the owner had to press the power key or reset by hand, ask them which and when: a real S2R that the alarm cannot wake through macOS's mask is possible." )$( [ $RUN = M ] && echo " M reading (worklog 2026-11-06 'run L'): L (macOS's wake mask) reset at about 146 s = WD1, not the 85 s timer. M is L with the owner pressing the power key once about 3 min after the push (about 50 s after echo mem). A resume = the key woke it: read the PMGR counters (SLP_S2R / SYS_S2R_AOP > 0 = the SoC really slept), psci_dbg[13] (3 = RVBAR path), 'sleep: wake status'; then expect the ANS dead and the dead-man reset. About 146 s again = the key does not wake it through macOS's mask either. Ask the owner when they pressed the key." )$( [ $RUN = W ] && echo " W reading (worklog 2026-11-06 'wake bisection'): no slpa, no S2R timer, aura-ctl 0; macOS's wake mask with wake_extra=$WX also enabled (the module now writes it at PM_SUSPEND_PREPARE: 'sleep: wake mask read ...' and 'sleep: wake mask now ...' reach the Pi kmsg before 'PM: suspend entry'; on wake 'sleep: wake status ...; wake mask restored'). A resume on the 30 s alarm = 'wake' (read 'sleep: wake status'); a reset about 145 s after echo mem (WD1) = 'nowake'. In the test kernel /boot may be unmounted: sudo mount /boot before arming (findmnt /boot). Record it with python3 tools/wake-bisect.py result wake|nowake (state in data/wake-bisect/state.json), commit, then arm the next unattended: WX=\$(python3 tools/wake-bisect.py next) bash harness/psci-efi/attended.sh W, until one bit is left; check that bit alone too. Then run L with that bit added (WX of the bit, run L with WX: set WX for L too), unattended per the owner's 15:15 rule. Stop and tell the owner after any hand reset, btrfs error or missing default boot.bin." )$( [ $RUN = P ] && echo " P reading (worklog 2026-11-06 'ISP_SYS release' entry): normal path, no slpa; pmp_report.test_release_ids=$PIDS also withdraws ISP_SYS (entry 12) in suspend_noirq. Expect dmesg 'TEST request 12 withdrawn for sleep: 0, ack 0x...' (with the display ones the ack word should reach 0) and 'asserted' after the wake, 'pmp requests after resume' back at 0xf000, a resume on the alarm with all CPUs, no new device errors (the SMC endpoint 0x20 line is old). If that holds, arm N unattended (L + this release; owner's 15:15 rule): bash harness/psci-efi/attended.sh N. A failure to re-assert (dev_err 'not asserted after sleep') or a hang = stop and record." )$( [ $RUN = N ] && echo " N reading: L (every macOS step found so far + macOS's wake mask) with ISP_SYS's PMP request withdrawn as well, so the PMP's request word is 0 before slpa as in macOS's trace (0x8300 -> 0x300 -> 0x200 -> 0, then the cores sleep). About 86 s = the timer's reset again (then the next difference in the trace: macOS requests and then clears the CPU complexes PCPM0/PCPM1 through the PMP's target word, and writes PMGR 0x2902801c0); a resume or dead-man push = read the PMGR counters (SLP_S2R, SYS_S2R_AOP > 0 = the SoC slept)." )$( case $RUN in G|H|I) echo " $RUN reading (worklog entry 'image 53'): D, D2, E reset about 85 s after echo mem (the S2R timer resets when the entry does not complete); F 145 s (WD1). About 85 s again = these quiesceHW steps are not what the entry waits for either; a resume (pmgr counters SLP_S2R > 0, psci_dbg[13] 3), a reset timed by the 30 s alarm, or any other time = the SoC got further. Then G before H." ;; esac ) PMP display requests released for sleep: $REL (pmp-release-modes deep; dmesg TEST request lines).$( [ -n "$NEXT" ] && echo " CHAIN: the owner is at the Mac for a series of attended runs (said on 2026-11-05 ~20:35: ready for attended tests. send notifications before starting each.). After recording this result and telling the owner (agent-notify), and only if this run left the Mac recovered (default boot, disk clean), arm the next: NEXT=\"$(echo $NEXT | cut -s -d" " -f2-)\" bash harness/psci-efi/attended.sh $(echo $NEXT | cut -d" " -f1) (it notifies the owner before it starts). If anything looks unsafe (a btrfs error, a hand reset, the default boot.bin missing), stop the chain and tell the owner." )${EXTRA:+ $EXTRA}
E
sed -n '/^UPDATE FROM GH-10/,$p' ~/.local/state/deepidle/prompt.txt >> $P
bash ~/Work/deepidle-harness/reboot.sh $P 30
